// This file is generated by AI.

// 选项卡右键菜单的内容测试。
//
// 菜单项是方案 §0.1 点名的硬约束: 「每个场景的菜单项一个都不能少」。原实现把菜单构建写在
// 组件里, 只能靠人点一遍; 抽到 `tabs/menu.ts` 之后就能在这里固定住, 少一项立刻红。

import { describe, expect, it, vi } from 'vitest';

import { buildTabMenu, hasLocalEntity, locateLabel, type TabMenuActions } from '../src/tabs/menu';
import { makeSceneTab, makeWorkbenchTab, type WorkbenchTabItem } from '../src/tabs/model';

function actions(): TabMenuActions & { calls: string[] } {
  const calls: string[] = [];
  return {
    calls,
    closeTab: (tab) => calls.push(`close:${tab.id}`),
    closeMany: (tabs) => calls.push(`closeMany:${tabs.map((tab) => tab.id).join('|')}`),
    sortTabs: () => calls.push('sort'),
    revealInFileManager: (path) => calls.push(`reveal:${path}`),
    locateInBrowser: (tab) => calls.push(`locate:${tab.id}`),
  };
}

const noDirty = () => false;

/** 三个场景 + 一个工作台: 覆盖"同类型/其它类型/左右侧"三种判定。 */
function fixture(): WorkbenchTabItem[] {
  return [
    makeSceneTab('C:\\p\\game\\scene\\a.txt', 'a.txt'),
    makeSceneTab('C:\\p\\game\\scene\\b.txt', 'b.txt'),
    makeSceneTab('C:\\p\\game\\scene\\c.txt', 'c.txt'),
    makeWorkbenchTab(),
  ];
}

function labels(items: ReturnType<typeof buildTabMenu>): string[] {
  return items.filter((item) => !item.separator).map((item) => item.label);
}

describe('buildTabMenu', () => {
  it('场景卡提供 10 个功能项 + 2 个分隔符', () => {
    const tabs = fixture();
    const items = buildTabMenu(tabs, tabs[0]!, actions(), noDirty);
    expect(labels(items)).toHaveLength(10);
    expect(items.filter((item) => item.separator)).toHaveLength(2);
  });

  it('每一项的文案与顺序都固定', () => {
    const tabs = fixture();
    const items = buildTabMenu(tabs, tabs[0]!, actions(), noDirty);
    expect(labels(items)).toEqual([
      '关闭',
      '关闭右侧',
      '关闭其它',
      '关闭同类型',
      '关闭其它类型',
      '关闭已保存',
      '关闭全部',
      '整理标签页',
      '在文件管理器中打开',
      '定位到场景浏览器',
    ]);
  });

  it('分隔符不与相邻项或首尾重复', () => {
    const tabs = fixture();
    const items = buildTabMenu(tabs, tabs[0]!, actions(), noDirty);

    expect(items[0]?.separator).toBeFalsy();
    expect(items.at(-1)?.separator).toBeFalsy();
    items.forEach((item, index) => {
      if (!item.separator) return;
      expect(items[index - 1]?.separator).toBeFalsy();
      expect(items[index + 1]?.separator).toBeFalsy();
    });
  });

  it('「关闭」只关这一张', () => {
    const tabs = fixture();
    const a = actions();
    const items = buildTabMenu(tabs, tabs[0]!, a, noDirty);
    items.find((item) => item.key === 'close')?.onClick?.();
    expect(a.calls).toEqual([`close:${tabs[0]!.id}`]);
  });

  it('「关闭右侧」只关右侧的那些', () => {
    const tabs = fixture();
    const a = actions();
    buildTabMenu(tabs, tabs[1]!, a, noDirty)
      .find((item) => item.key === 'close-right')
      ?.onClick?.();
    expect(a.calls).toEqual([`closeMany:${tabs[2]!.id}|${tabs[3]!.id}`]);
  });

  it('「关闭其它」把自己留下', () => {
    const tabs = fixture();
    const a = actions();
    buildTabMenu(tabs, tabs[0]!, a, noDirty)
      .find((item) => item.key === 'close-others')
      ?.onClick?.();
    expect(a.calls[0]).not.toContain(tabs[0]!.id);
    expect(a.calls[0]).toContain(tabs[1]!.id);
  });

  it('「关闭同类型」连当前这一张一起关', () => {
    const tabs = fixture();
    const a = actions();
    buildTabMenu(tabs, tabs[0]!, a, noDirty)
      .find((item) => item.key === 'close-same-kind')
      ?.onClick?.();
    // 同类型的筛选**包含自己**, 因此当前卡与同类型的卡一起关 (有未保存改动时走关闭确认)
    expect(a.calls[0]).toBe(`closeMany:${tabs[0]!.id}|${tabs[1]!.id}|${tabs[2]!.id}`);
  });

  it('「关闭其它类型」只挑不同 kind 的', () => {
    const tabs = fixture();
    const a = actions();
    buildTabMenu(tabs, tabs[0]!, a, noDirty)
      .find((item) => item.key === 'close-other-kind')
      ?.onClick?.();
    expect(a.calls[0]).toBe(`closeMany:${tabs[3]!.id}`);
  });

  it('「关闭已保存」跳过有未保存改动的', () => {
    const tabs = fixture();
    const a = actions();
    // 让 b 变脏
    const dirty = (tab: WorkbenchTabItem) => tab.id === tabs[1]!.id;
    const items = buildTabMenu(tabs, tabs[0]!, a, dirty);
    items.find((item) => item.key === 'close-saved')?.onClick?.();
    expect(a.calls[0]).not.toContain(tabs[1]!.id);
    expect(a.calls[0]).toContain(tabs[2]!.id);
  });

  it('「关闭全部」包含自己', () => {
    const tabs = fixture();
    const a = actions();
    buildTabMenu(tabs, tabs[0]!, a, noDirty)
      .find((item) => item.key === 'close-all')
      ?.onClick?.();
    for (const tab of tabs) expect(a.calls[0]).toContain(tab.id);
  });

  it('只有一张卡时「关闭其它」「关闭其它类型」整项不出现', () => {
    const only: WorkbenchTabItem[] = [makeSceneTab('C:\\p\\game\\scene\\a.txt', 'a.txt')];
    const items = buildTabMenu(only, only[0]!, actions(), noDirty);

    // 这两项是"条件出现"而不是"永远列出但置灰": 单卡时根本不存在
    expect(items.find((item) => item.key === 'close-others')).toBeUndefined();
    expect(items.find((item) => item.key === 'close-other-kind')).toBeUndefined();
    // 「关闭右侧」仍然列出但置灰, 「关闭同类型」可用 —— 它包含自己
    expect(items.find((item) => item.key === 'close-right')?.disabled).toBe(true);
    expect(items.find((item) => item.key === 'close-same-kind')?.disabled).toBeFalsy();
  });

  it('已经有序时「整理标签页」置灰', () => {
    // orderTabs 把配音工作台排在最前, 因此"有序"的夹具里工作台必须在前
    const ordered: WorkbenchTabItem[] = [
      makeWorkbenchTab(),
      makeSceneTab('C:\\p\\game\\scene\\a.txt', 'a.txt'),
      makeSceneTab('C:\\p\\game\\scene\\b.txt', 'b.txt'),
    ];
    const items = buildTabMenu(ordered, ordered[1]!, actions(), noDirty);
    expect(items.find((item) => item.key === 'sort')?.disabled).toBe(true);
  });

  it('顺序乱了时「整理标签页」可用', () => {
    const tabs = fixture();
    // 夹具里工作台在最后, 而 orderTabs 要求它在最前 -> 未排序
    const items = buildTabMenu(tabs, tabs[0]!, actions(), noDirty);
    expect(items.find((item) => item.key === 'sort')?.disabled).toBe(false);
  });

  it('差异卡没有磁盘位置时不提供「打开/定位」', () => {
    const tabs = fixture();
    const diff = {
      id: 'diff:x',
      kind: 'diff' as const,
      title: '差异',
      tooltip: '差异',
      file: 'game/scene/a.txt',
      diffKind: 'unstaged' as const,
    };
    const items = buildTabMenu([...tabs, diff], diff, actions(), noDirty);

    expect(items.find((item) => item.key === 'reveal')).toBeUndefined();
    expect(items.find((item) => item.key === 'locate')).toBeUndefined();
    expect(hasLocalEntity(diff)).toBe(false);
  });

  it('「整理标签页」把有序结果交给 action', () => {
    const tabs = fixture();
    const a = actions();
    buildTabMenu(tabs, tabs[0]!, a, noDirty)
      .find((item) => item.key === 'sort')
      ?.onClick?.();
    expect(a.calls).toEqual(['sort']);
  });

  it('定位文案随类型变化', () => {
    const scene = makeSceneTab('C:\\p\\game\\scene\\a.txt', 'a.txt');
    expect(locateLabel(scene)).toBe('定位到场景浏览器');
  });
});

describe('菜单项回调', () => {
  it('每一项都挂了 onClick（漏挂等于点了没反应）', () => {
    const tabs = fixture();
    const items = buildTabMenu(tabs, tabs[0]!, actions(), noDirty);
    for (const item of items) {
      if (item.separator) continue;
      expect(typeof item.onClick, `${item.key} 没有 onClick`).toBe('function');
    }
  });

  it('不修改传入的数组', () => {
    const tabs = fixture();
    const before = [...tabs];
    buildTabMenu(tabs, tabs[0]!, actions(), noDirty);
    expect(tabs).toEqual(before);
  });

  it('对不在列表里的选项卡也不抛错', () => {
    const tabs = fixture();
    const outsider = makeSceneTab('C:\\p\\game\\scene\\z.txt', 'z.txt');
    expect(() => buildTabMenu(tabs, outsider, actions(), noDirty)).not.toThrow();
    expect(vi.isMockFunction(actions().closeTab)).toBe(false);
  });
});
